arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"channel":"C_INC","limit":100}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d.get('error')); sys.exit()
for m in d['messages']:
    print(m.get('ts'), '|', m.get('user'), '|', (m.get('text') or '')[:120].replace(chr(10),' '))
    if 'reactions' in m:
        for r in m['reactions']:
            print('   REACT:', r['name'], r['users'])
"

